using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Sigov.Api.Contracts;using Sigov.Application.Abstractions;using Sigov.Application.Educacao.Avancada;
namespace Sigov.Api.Controllers;
[Authorize] public abstract class EducacaoAvancadaControllerBase:ControllerBase{protected readonly ICurrentTenant Tenant;protected readonly ICurrentUser User;protected EducacaoAvancadaControllerBase(ICurrentTenant t,ICurrentUser u){Tenant=t;User=u;}protected long TenantId()=>Tenant.TenantId??throw new InvalidOperationException("Tenant autenticado é obrigatório.");protected EducacaoAvancadaContext Contexto()=>new(TenantId(),Tenant.EntidadeId,Tenant.ExercicioId,User.UsuarioId,HttpContext.TraceIdentifier);protected ActionResult<ApiResponse<T>> OkResponse<T>(T x)=>Ok(ApiResponse<T>.Ok(x,correlationId:HttpContext.TraceIdentifier));}
